<?php
namespace App\Http\Requests;
use Illuminate\Foundation\Http\FormRequest;
class StoreNotificationRequest extends FormRequest { public function authorize(): bool{return true;} protected function prepareForValidation(): void { if(!$this->input('idempotency_key') && $this->header('Idempotency-Key')) $this->merge(['idempotency_key'=>$this->header('Idempotency-Key')]); } public function rules(): array{return ['recipient'=>['required','string','max:320'],'channel'=>['required','in:sms,email,push'],'content'=>['required','string','max:10000'],'priority'=>['sometimes','in:high,normal,low'],'idempotency_key'=>['sometimes','nullable','string','max:255'],'scheduled_at'=>['sometimes','nullable','date','after_or_equal:now']];} public function withValidator($validator): void { $validator->after(function($v){$channel=$this->input('channel');$content=(string)$this->input('content');$limit=match($channel){'sms'=>1600,'push'=>4096,default=>10000};if(mb_strlen($content)>$limit)$v->errors()->add('content',"Content exceeds the {$channel} limit of {$limit} characters.");if($channel==='email' && !filter_var($this->input('recipient'),FILTER_VALIDATE_EMAIL))$v->errors()->add('recipient','A valid email address is required for email notifications.');});} }
